import os
keep = "step_94208000.pt"
removed, failed = [], []
for f in sorted(os.listdir(".")):
    if f.startswith("step_") and f.endswith(".pt") and f != keep:
        try:
            os.remove(f); removed.append(f)
        except Exception as e:
            failed.append((f, str(e)))
print("removed:", len(removed))
for r in removed: print("  -", r)
print("failed:", failed)
print("remaining:", sorted(os.listdir(".")))
EOF
